-- Check if there's a column that could be "NIC score" - maybe it's netpatscore from pattern_scores
-- Let's also check what clustrole values exist
SELECT DISTINCT clustrole FROM moderationaction;

-- Let's look at the full join path and understand the data better
-- Check how many records exist and what accounts have moderation actions with positive netinflscore
SELECT COUNT(*) FROM moderationaction;

-- Let me check the relationship chain: account -> profile -> sessionbehavior -> networkmetrics/contentbehavior -> moderationaction
-- And also check if netpatscore (network pattern score) could be the "NIC" score
SELECT COUNT(*) FROM securitydetection;

SELECT MIN((detection_score_profile->'pattern_scores'->>'netpatscore')::numeric), 
       MAX((detection_score_profile->'pattern_scores'->>'netpatscore')::numeric)
FROM securitydetection;

-- 998 accounts, 998 moderation actions. Let me check if there's a direct link through profile or contentbehavior
-- Maybe the path is simpler - account -> contentbehavior -> moderationaction
SELECT COUNT(DISTINCT cb.cntref) FROM contentbehavior cb;

-- Let me check if networkmetrics has a direct path to account
-- sessionbehavior -> networkmetrics (via netsessref)
SELECT COUNT(DISTINCT sb.sessref) FROM sessionbehavior sb JOIN networkmetrics nm ON sb.sessref = nm.netsessref;

-- Let me try with netpatscore as the "NIC score" (Network INfluence Component? Network PATtern Score?)
-- and see if filtering by positive values changes anything
SELECT COUNT(*) FROM securitydetection WHERE (detection_score_profile->'pattern_scores'->>'netpatscore')::numeric > 0;

-- Let me check if there's a column I might have missed in any table that could be "nic" related
SELECT table_name, column_name FROM information_schema.columns 
WHERE table_schema = 'public' AND (column_name LIKE '%nic%' OR column_name LIKE '%influence%' OR column_name LIKE '%promin%');
